package gg.pixelkingdomwars.nativeclient.divinefragments
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class DivineFragmentProtocolTest {
 private val f=Json.parseToJsonElement(javaClass.classLoader!!.getResource("divine-fragment-vectors.json")!!.readText()).jsonObject
 private val r=DivineFragmentRules.from(f.fo("rules"));private val a=f.fo("award");private val c=f.fo("consent");private val d=f.fo("delivery");private val e=f.fo("entitlement")
 private fun changed(o:JsonObject,k:String,v:JsonElement)=JsonObject(o+(k to v))
 private fun reject(block:()->Unit){assertTrue(runCatching(block).isFailure)}
 @Test fun `shared validated original vectors bind policy earning delivery and permanent cumulative claim`(){assertEquals(r.raw,DivineFragmentRules.installed(f.fo("policy"),f.fo("catalogue")).raw);r.award(a);assertEquals(d,r.match(d,"delivery",c));r.match(f.fo("claim"),"claim",f.fo("claimConsent"));r.entitlement(e)}
 @Test fun `new earning tax and fractional carry cannot be replaced by reward exemptions`(){for((k,v) in listOf("tax" to "0","net" to "14","carryAfter" to "0","carryBefore" to "10000","gross" to "15"))reject{r.award(changed(a,k,JsonPrimitive(v)))};val zero=JsonObject(a+mapOf("winnerCount" to JsonPrimitive(0),"poolDisposition" to JsonPrimitive("held_zero_winners")));r.award(zero);reject{r.award(changed(a,"winnerCount",JsonPrimitive(0)))}}
 @Test fun `strings are exact int64 quantities and timestamps must identify actual UTC instants`(){for(v in listOf(JsonPrimitive(12),JsonPrimitive("01"),JsonPrimitive("9223372036854775808"),JsonPrimitive("1e2")))reject{r.receipt(changed(d,"quantity",v),"delivery")};for(v in listOf("2026-02-30T00:00:00.000Z","2026-09-28T00:00:00Z","2026-09-28T00:00:00.000+00:00"))reject{r.award(changed(a,"earnedAt",JsonPrimitive(v)))}}
 @Test fun `wallet bytes source fields and site range fail closed`(){reject{r.award(changed(a,"wallet",JsonPrimitive("1".repeat(33))))};reject{r.award(changed(a,"site",JsonPrimitive("divine-individual-000")))};reject{r.award(JsonObject(a+("authority" to JsonPrimitive(true))))};reject{r.award(changed(a,"weekStart",a.getValue("earnedAt")))}}
 @Test fun `receipt cannot redirect the original destination wallet event or request`(){for(k in listOf("baseId","eventId","idempotencyKey"))reject{r.match(changed(d,k,JsonPrimitive("00000000-0000-4000-8000-000000000099")),"delivery",c)};reject{r.match(changed(d,"wallet",JsonPrimitive("11111111111111111111111111111111")),"delivery",c)};reject{r.receipt(changed(d,"stockAfter",JsonPrimitive("0")),"delivery")}}
 @Test fun `cumulative pool cannot overpay reset prior claim or claim zero-winner share`(){val v=f.fo("claim");for((k,n) in listOf("quantity" to "4","previousTotal" to "6","cumulativeTotal" to "6"))reject{r.receipt(changed(v,k,JsonPrimitive(n)),"claim")};reject{r.receipt(changed(v,"winnerCount",JsonPrimitive(0)),"claim")}}
 @Test fun `one term page enforces monotone cursor unique original spots and equal pool`(){fun page(rows:List<JsonObject>)=buildJsonObject{put("version",1);put("wallet",a.getValue("wallet"));put("rows",JsonArray(rows));put("nextCursor",e.getValue("termId"))}
 r.page(page(listOf(e)),a.ft("wallet"),"claims",null);reject{r.page(page(listOf(e,e)),a.ft("wallet"),"claims",null)};reject{r.page(page(listOf(e)),a.ft("wallet"),"claims",e.ft("termId"))};reject{r.page(page(listOf(e,changed(e,"poolTotal",JsonPrimitive("12")))),a.ft("wallet"),"claims",null)}}
 @Test fun `commands cannot carry quantities source authority or raw resource aliases`(){val q=c.fo("request");for(k in listOf("quantity","source","termId","resourceId"))reject{DivineFragmentProtocol.request("POST","/divine-fragments/events/${a.ft("eventId")}/delivery",emptyMap(),JsonObject(q+(k to JsonPrimitive("1"))))};reject{DivineFragmentProtocol.request("POST","/divine-fragments/enroll",emptyMap(),q)};reject{DivineFragmentProtocol.request("GET","/divine-fragments/awards",mapOf("wallet" to a.ft("wallet")),null)}}
 @Test fun `event and recovery envelope cannot omit or borrow accepted identities`(){val v=buildJsonObject{put("version",1);put("wallet",a.getValue("wallet"));put("eventId",a.getValue("eventId"));put("enrolled",true);put("settled",true);put("award",a);put("delivery",d)};r.event(v,a.ft("wallet"),a.ft("eventId"));reject{r.event(changed(v,"settled",JsonPrimitive(false)),a.ft("wallet"),a.ft("eventId"))};val envelope=buildJsonObject{put("version",1);put("wallet",a.getValue("wallet"));put("idempotencyKey",d.getValue("idempotencyKey"));put("receipt",d)};r.envelope(envelope,"delivery",c);reject{r.envelope(changed(envelope,"idempotencyKey",a.getValue("eventId")),"delivery",c)}}
 @Test fun `exact permanent term GET admits only an original UUID without cursor or client authority`(){val path="/divine-fragments/seeker/terms/${e.ft("termId")}";DivineFragmentProtocol.request("GET",path,emptyMap(),null);reject{DivineFragmentProtocol.request("GET",path,mapOf("cursor" to e.ft("termId")),null)};reject{DivineFragmentProtocol.request("POST",path,emptyMap(),buildJsonObject{})};reject{DivineFragmentProtocol.request("GET","/divine-fragments/seeker/terms/../claims",emptyMap(),null)}}
}
